gabarito.solution:
package student

func SumConcurrent(nums []int) int {
	ch := make(chan int, len(nums))
	for _, n := range nums {
		go func(v int) {
			ch <- v
		}(n)
	}
	total := 0
	for range nums {
		total += <-ch
	}
	return total
}

