package student

import (
	"database/sql"

	_ "modernc.org/sqlite"
)

func CountAdults(rows [][2]any) int {
	db, err := sql.Open("sqlite", ":memory:")
	if err != nil {
		return 0
	}
	defer db.Close()
	if _, err := db.Exec(`CREATE TABLE people (name TEXT, age INTEGER)`); err != nil {
		return 0
	}
	for _, r := range rows {
		db.Exec(`INSERT INTO people (name, age) VALUES (?, ?)`, r[0], r[1])
	}
	var n int
	db.QueryRow(`SELECT COUNT(*) FROM people WHERE age >= 18`).Scan(&n)
	return n
}

