func search(v []int, target int) int {
    lo, hi := 0, len(v)-1
    for lo <= hi {
        mid := (lo + hi) / 2
        if v[mid] == target {
            return mid
        }
        if v[mid] < target {
            lo = mid + 1
        } else {
            hi = mid - 1
        }
    }
    return -1
}

